def dump(n,d):(O/n).write_text(json.dumps(d,indent=2)+'\n')
def main():
 now=datetime.datetime.now(datetime.timezone.utc).isoformat();base=read(O/'integration-baseline.json');assert subprocess.check_output(['git','rev-parse','HEAD'],cwd=P,text=True).strip()==base['head'] and len(read(B/'tasks.json')['tasks'])==545
 before=snap(ROOT);author_before=snap(AUTHOR);assert author_before==read(C/'observed-root.json')['root'];dump('observed-root.json',{'observed_utc':now,'root':before,'limits':'Snapshot excludes root-directory mode.'})
 st=read(O/'task-status.json')['structuredContent'];assert st['status']=='completed' and st['workState']=='result_available' and not st['hasPendingChildRuns'] and not st['hasPendingQuestion'];assert 'PASS' in st['summary'] and all(v in st['summary'] and sha(ROOT/n)==v for n,v in ANCHORS.items());assert sha(AUTHOR/'scope-frozen.md')==SCOPE and sha(AUTHOR/'author-proof.md')==PROOF
 m=read(ROOT/'MANIFEST.json');assert len(m['files'])==25 and len(m['directories'])==8;assert {n for n,e in before.items() if e['kind']=='file'}==set(m['files'])|set(ANCHORS) and {n for n,e in before.items() if e['kind']=='directory'}==set(m['directories'])
 for n,e in m['files'].items():assert (ROOT/n).stat().st_size==e['size'] and sha(ROOT/n)==e['sha256'] and oct(stat.S_IMODE((ROOT/n).stat().st_mode))==e['mode']
 for n,v in m['directories'].items():assert oct(stat.S_IMODE((ROOT/n).stat().st_mode))==v
 originals=read(ROOT/'private/selected-incoming-identities.json')['files'];assert len(originals)==26;stable=[]
