 source=read(ROOT/'private/source-authentication.json');tp=P/'sources/preprints-tree.json';assert sha(tp)==source['complete_tree_sha256']=='eeecc1da49aa02877d137c4fb90339aca460ec27718b623916368bc08dc5e09b';tree=read(tp);assert len(tree['tree'])==13223 and not tree['truncated'];e=source['canonical_entry'];node=next(x for x in tree['tree'] if x['path']==e['path']);data=(P/source['selected_incoming_original']).read_bytes();assert len(data)==source['size']==node['size']==15479 and hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest()==source['verified_git_blob']==node['sha'] and hashlib.sha256(data).hexdigest()==source['sha256']
 primary=read(ROOT/'private/primary-selection.json');r=primary['receipt_record'];assert (P/primary['incoming_original']).stat().st_size==r['bytes'] and sha(P/primary['incoming_original'])==r['sha256'] and sha(P/primary['incoming_text'])==r['extracted_text_sha256'];assert len(list((ROOT/'private/render').glob('*.png')))==3
 for e in read(ROOT/'private/diagnostic-copy-identities.json'):
  p=P/e['incoming_original'];q=ROOT/e['selected_adapted_copy'];assert p.stat().st_size==e['size'] and sha(p)==e['sha256'] and sha(q)==e['copy_sha256'];text=p.read_text();assert text.count('frontier/campaigns/2026-10-14/fresh-structural-discovery-r161')==1;assert text.replace('frontier/campaigns/2026-10-14/fresh-structural-discovery-r161','frontier/campaigns/2026-10-14/structural-r161-proof-r1')==q.read_text()
 ctl=read(ROOT/'private/copied-control-results.json');fixture=ROOT/'private/controls/selected-copy';assert len(ctl['controls'])==5 and all(e['expected_accept']==e['actual_accept'] for e in ctl['controls']) and ctl['original_selected_note_bytes_mode_nlink_mtime_unchanged'];assert all(sha(fixture/n)==v for n,v in ctl['selected_copy_anchors'].items()) and len(read(fixture/'MANIFEST.json')['files'])==1 and (fixture/'selected-note.md').read_bytes()==(ROOT/'notes/01-mathematical-checks.md').read_bytes()
 cases=[]
 with tempfile.TemporaryDirectory(prefix='correctness-copy-',dir=O) as tmp:
  copy=Path(tmp)/'packet';shutil.copytree(ROOT,copy);copy.chmod(copy.stat().st_mode|0o200);copied_before=snap(copy);args=[str(copy),*ANCHORS.values()]
  def check(label,want,custom=None):
   state=snap(copy);r=subprocess.run([sys.executable,'-I','-B',str(copy/'tools/verify.py'),*(custom or args)],capture_output=True,text=True,timeout=30);assert (r.returncode==0)==want,(label,r.stdout,r.stderr);assert snap(copy)==state;cases.append({'case':label,'expected_pass':want,'returncode':r.returncode,'fixture_unchanged':True,'stdout':r.stdout.strip(),'stderr':r.stderr.strip()})
  check('baseline_full_packet',True);q=copy/'notes/01-mathematical-checks.md';data=q.read_bytes();q.write_bytes(data+b'\nCONTROL\n');check('changed_payload',False);q.unlink();check('missing_payload',False);q.write_bytes(data);q.chmod(copied_before['notes/01-mathematical-checks.md']['mode']);q=copy/'.extra';q.write_text('extra');check('hidden_extra',False);q.unlink();q=copy/'extra-empty';q.mkdir();check('extra_empty_directory',False);q.rmdir();wrong=args.copy();wrong[3]='0'*64;check('wrong_report_anchor',False,wrong);q=copy/'notes/01-mathematical-checks.md';q.chmod(q.stat().st_mode^0o100);check('changed_payload_mode',False);q.chmod(copied_before['notes/01-mathematical-checks.md']['mode']);check('restored',True);assert snap(copy)==copied_before
  out=Path(tmp)/'independent';(out/'tools').mkdir(parents=True);(out/'private').mkdir();script=out/'tools/independent_checks.py';shutil.copyfile(ROOT/'tools/independent_checks.py',script);r=subprocess.run([sys.executable,'-I','-B',str(script)],cwd=P,capture_output=True,text=True,timeout=60);assert r.returncode==0 and read(out/'private/independent-results.json')==read(ROOT/'private/independent-results.json');result=read(out/'private/independent-results.json');assert (result['feasible_table_cases'],result['containment_checks'],result['joint_tables'],result['joint_tables_with_equal_collapsed_tables'])==(156,4024,210,30);dump('finite-diagnostic.json',{'stdout':r.stdout,'unmodified_program_copied_into_temporary_root':True,'saved_record_equal':True,'feasible_table_cases':156,'containment_checks':4024,'joint_tables':210,'temporary_outputs_removed':True,'limits':'Finite evidence only;universal mathematical verdict comes from independent review derivation,not enumeration.'})
 assert snap(ROOT)==before and snap(AUTHOR)==author_before and all(sha(P/e['path'])==e['sha256'] for e in stable) and all(sha(P/p)==v for p,v in base['protected_unrelated_sha256'].items())
 dump('copied-controls.json',{'cases':cases,'positive_cases':2,'negative_cases':6,'copy_removed':True,'whole_actual_review_and_author_roots_unchanged':True,'limits':'Manifest binds files/directories/bytes/modes;no root-directory mode,timestamps or atimes binding.'})
 dump('input-authentication.json',{'review_payload_files':25,'source_blobs':1,'source_bytes':15479,'primary_original_pdf_text_pairs':1,'render_members':3,'stable_original_identities':26,'adapted_diagnostic_copies':2,'copied_fixture_members':1,'limits':'Local byte/path/member authentication only. Parent did not freshly read protected source/primary/visual proof bodies;original rights unchanged.'})
 dump('replay.json',{'observed_utc':now,'external_handoff_anchors':ANCHORS,'payload_files':25,'whole_root_files':28,'subdirectories':8,'scope_frozen_sha256':SCOPE,'author_proof_sha256':PROOF,'source_blobs':1,'primary_pdf_text_pairs':1,'render_members':3,'stable_named_originals':stable,'artifact_cases':8,'negative_cases':6,'finite_table_cases':156,'containment_checks':4024,'joint_tables':210,'review_and_author_roots_unchanged':True,'limits':'Artifact/finite evidence;only full correctness PASS is adopted,no contribution or acceptance.'})
 print(json.dumps({'review_payload':25,'files':28,'dirs':8,'stable_originals':26,'artifact_cases':8,'independent_table_cases':156,'containment_checks':4024,'joint_tables':210}))
